            color = grid[r][c]
            if color == 3:
                continue
            if (r > 0 and r + 1 < h and c > 0 and c + 1 < w
                    and grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 3):
                (blank if color == 0 else colored).append((r, c, color))

    def extend(r, c, color, dr, dc, overwrite):
        own_arms = {(r-1, c), (r+1, c), (r, c-1), (r, c+1)}
        y, x = r + dr, c + dc
        while 0 <= y < h and 0 <= x < w:
            if grid[y][x] == 3 and (y, x) not in own_arms:
                break
            if grid[y][x] == 0:
                out[y][x] = color
            y += dr
            x += dc

    # Horizontal rays stop at another cross's 3 markers.
    for r, c, color in colored:
        extend(r, c, color, 0, -1, False)
        extend(r, c, color, 0, 1, False)
    # A hollow cross cuts horizontal rays along its row.
    for r, c, _ in blank:
